package ports

import (
	"errors"
	"os"
)

// No reader exists for this OS: every identity is unknown, so every row is
// unverifiable and Kill refuses it.
func readIdentity(int) (uint64, error) { return 0, errors.ErrUnsupported }

func heldIdentity(*os.Process, int) (uint64, error) { return 0, errors.ErrUnsupported }

func isNoSuchProcess(error) bool { return false }
package ports

import (
	"errors"
	"fmt"
	"os"

	"golang.org/x/sys/windows"
)

// creationOf reads the CreationTime of a process handle as one 64-bit FILETIME.
func creationOf(h windows.Handle) (uint64, error) {
	var creation, exit, kernel, user windows.Filetime
	if err := windows.GetProcessTimes(h, &creation, &exit, &kernel, &user); err != nil {
		return 0, fmt.Errorf("reading the creation time: %w", err)
	}
	return uint64(creation.HighDateTime)<<32 | uint64(creation.LowDateTime), nil
}

// readIdentity opens pid with the least rights that read its times. A refusal of
// the system stays readable as os.ErrPermission, and an unknown PID reads as
// os.ErrProcessDone.
func readIdentity(pid int) (uint64, error) {
	h, err := windows.OpenProcess(windows.PROCESS_QUERY_LIMITED_INFORMATION, false, uint32(pid)) //nolint:gosec // a PID fits in a DWORD
	if err != nil {
		if errors.Is(err, windows.ERROR_INVALID_PARAMETER) {
			return 0, fmt.Errorf("opening the process: %w", os.ErrProcessDone)
		}
		return 0, fmt.Errorf("opening the process: %w", err)
	}
	defer windows.CloseHandle(h) //nolint:errcheck // nothing to do if closing fails
	return creationOf(h)
}

// heldIdentity reads the creation time on the handle p holds, the one
// os.FindProcess opened: the PID cannot be reassigned while it is open.
func heldIdentity(p *os.Process, _ int) (uint64, error) {
	var raw uint64
	var readErr error
	if err := p.WithHandle(func(h uintptr) { raw, readErr = creationOf(windows.Handle(h)) }); err != nil {
		return 0, err
	}
	return raw, readErr
}

// isNoSuchProcess tells the failure of os.FindProcess for a PID nobody holds.
func isNoSuchProcess(err error) bool { return errors.Is(err, windows.ERROR_INVALID_PARAMETER) }
// Package ports reads the machine's socket table, and ends a process holding
// one.
//
// It answers for **this machine**. That is the whole reason it exists: the
// Ports tab used to run `ss` inside `docker run --rm --net=host --pid=host
// --privileged`, and on Docker Desktop `--net=host` is the namespace of the
// Linux VM, not of the host. The tab therefore listed the VM's sockets — its
// NFS daemons, with two-digit PIDs — while not one of the host's listening
// sockets appeared, and `K` killed a process of the VM under the impression it
// was freeing a port on the machine (D55).
//
// The same sentence has been written at the top of `docker.runDiagHost` since
// §3.33 rapatriated DNS, ICMP, TCP, TLS and HTTP for exactly this reason.
// `RunSS` and `KillProcess` were the two that stayed behind.
//
// Nothing here starts a container, and nothing here needs Docker: the Ports tab
// now works on a machine that has none.
package ports

import (
	"context"
	"fmt"
	"net"
	"strconv"

	gnet "github.com/shirou/gopsutil/v4/net"
	gproc "github.com/shirou/gopsutil/v4/process"
)

// Socket is one row of the table: a socket, and the process holding it.
//
// Every field but Identity is a string because it is displayed, and the PID
// in particular is what the table is keyed on — an int would have to be
// formatted at each of the sites that compare it.
type Socket struct {
	Protocol  string // tcp or udp, whichever family the address is on
	State     string // LISTEN, ESTABLISHED, UNCONN, TIME_WAIT…
	LocalAddr string
	PeerAddr  string
	PID       string // empty when no process could be attributed
	Process   string
	// Identity is not displayed: it is what Kill verifies the PID against. It is
	// unknown when PID is empty or the process could not be read.
	Identity Identity
}

// List returns the machine's TCP and UDP sockets.
//
// resolve asks for the addresses to be reported as host names where reverse DNS
// answers; see resolveAddrs for what that does and does not cover.
func List(ctx context.Context, resolve bool) ([]Socket, error) {
	// The instant is taken before the snapshot, never after: on Windows a process
	// created later than it is not one of the rows (see attachIdentities).
	listedAt := now()
	conns, err := gnet.ConnectionsWithContext(ctx, "inet")
	if err != nil {
		return nil, fmt.Errorf("reading the socket table: %w", err)
	}

	names := processNames(ctx)

	sockets := make([]Socket, 0, len(conns))
	for _, c := range conns {
		sockets = append(sockets, toSocket(c, names))
	}
	attachIdentities(sockets, listedAt)

	if resolve {
		resolveAddrs(ctx, sockets)
	}
	return sockets, nil
}

// toSocket turns one connection into a row.
func toSocket(c gnet.ConnectionStat, names map[int32]string) Socket {
	s := Socket{
		Protocol:  protocolOf(c.Type),
		State:     stateOf(c.Status, c.Type),
		LocalAddr: formatAddr(c.Laddr, c.Family),
		PeerAddr:  formatAddr(c.Raddr, c.Family),
	}
	// A PID of zero is not a process: it is the system declining to attribute
	// the socket to one, and `K` keys on this field. Left as "0" it would give
	// the row something that looks killable, and Kill would then be asked to
	// signal a process id that means "every process in the group" on Unix.
	if c.Pid > 0 {
		s.PID = strconv.FormatInt(int64(c.Pid), 10)
		s.Process = names[c.Pid]
	}
	return s
}

// Kill sends SIGKILL — TerminateProcess on Windows — to the process holding a
// socket.
//
// It replaces `docker run --pid=host --privileged <image> kill -9 <pid>`, which
// on Docker Desktop signalled a process of the VM (D55). The consequence worth
// knowing is that DevDesk now signals with the rights it actually has: another
// user's process, or a service, comes back as a refusal from the operating
// system rather than as a success against the wrong machine.
//
// The signal leaves through procOS.kill, the single point of the package that
// sends one; in a test binary it panics unless the test substituted procOS
// (DEVDESK-708).
//
// DevDesk itself, its direct parent, PID 1 and, on Windows, PIDs 0 and 4 are
// refused with a *ProtectedError before anything is sent. A pid outside int32
// or not in canonical form is refused first, as "not a process id" (parsePID).
// The protection check comes
// before the n <= 0 one because PID 0 is a protected process on Windows.
//
// listed is the identity the row carried (DEVDESK-709), after ConfirmIdentity
// for a deferred one. Anything but a known identity is refused with an
// *UnverifiableError, and the signal goes only to the process that has it: if
// the PID is held by another one the answer is an *IdentityChangedError.
func Kill(pid string, listed Identity) error {
	n, ok := parsePID(pid)
	if !ok {
		return fmt.Errorf("not a process id: %q", pid)
	}
	if p := protectionOf(n); p != Unprotected {
		return &ProtectedError{PID: n, Protection: p}
	}
	if n <= 0 {
		return fmt.Errorf("not a process id: %q", pid)
	}
	if listed.kind != identityKnown {
		return &UnverifiableError{PID: n}
	}
	if err := procOS.kill(n, listed); err != nil {
		return fmt.Errorf("killing process %s: %w", pid, err)
	}
	return nil
}

// processNames maps PID to process name, from **one** enumeration.
//
// The obvious implementation — process.NewProcess(pid).Name() per socket — is
// the one that does not work. On Windows that path goes through OpenProcess and
// QueryFullProcessImageName, which needs rights over the target: measured on
// this machine, 98 of 189 sockets came back "Access denied", and the Process
// column would have been empty for every service on the box. Processes() reads
// a Toolhelp32 snapshot instead and named all 294 processes in 11 ms, elevated
// or not.
//
// So the bulk enumeration is not an optimisation over the per-PID call. It is
// the difference between a column that is filled in and one that is not.
//
// A failure here is not a failure of the listing: a table of sockets with no
// process names still says which ports are open, and that is most of what it is
// read for.
func processNames(ctx context.Context) map[int32]string {
	procs, err := gproc.ProcessesWithContext(ctx)
	if err != nil {
		return nil
	}
	names := make(map[int32]string, len(procs))
	for _, p := range procs {
		if name, err := p.NameWithContext(ctx); err == nil && name != "" {
			names[p.Pid] = name
		}
	}
	return names
}

// protocolOf reports tcp or udp. Both families print the same word, as `ss`
// does: the address beside it already says which one it is on.
func protocolOf(sockType uint32) string {
	switch sockType {
	case 1: // SOCK_STREAM
		return "tcp"
	case 2: // SOCK_DGRAM
		return "udp"
	default:
		return ""
	}
}

// stateOf normalises the state, and neither substitution is cosmetic.
//
// An unconnected UDP socket is reported as "NONE" on Linux and as nothing at all
// on Windows, so the same socket read differently depending on where DevDesk was
// running. UNCONN is what the table showed when `ss` produced it, and it is what
// the socket is.
//
// ESTABLISHED is shortened to ESTAB for the reason `ss` shortens it: the State
// column is ten cells wide, so the long spelling is truncated to "ESTABLISHE" —
// and the filter token the user toggles with `e` reads better short.
func stateOf(status string, sockType uint32) string {
	if sockType == 2 && (status == "" || status == "NONE") {
		return "UNCONN"
	}
	if status == "ESTABLISHED" {
		return "ESTAB"
	}
	return status
}

// formatAddr renders an endpoint the way the table has always shown one:
// host:port, bracketed for IPv6, and the wildcard form for the peer of a socket
// that has none.
func formatAddr(a gnet.Addr, family uint32) string {
	if a.IP == "" && a.Port == 0 {
		if isIPv6(family) {
			return "[::]:*"
		}
		return "0.0.0.0:*"
	}
	return net.JoinHostPort(a.IP, strconv.FormatUint(uint64(a.Port), 10))
}

// isIPv6 reports whether the address family is AF_INET6. The constant differs
// between platforms — 23 on Windows, 10 on Linux, 30 on Darwin — and gopsutil
// passes through whichever the kernel used, so all three are named here rather
// than compared against one.
func isIPv6(family uint32) bool {
	return family == 23 || family == 10 || family == 30
}

package ports

import (
	"bytes"
	"errors"
	"fmt"
	"math"
	"os"
	"strconv"
	"testing"
	"time"
)

// Identity tells one process from a later one that got the same PID
// (DEVDESK-709). It is the creation stamp in the operating system's own unit,
// read once per PID when the table is listed. It is opaque: the interface only
// asks Verifiable, and this package compares. The zero value is "unknown", which
// Kill refuses, so a caller that forgets the identity cannot send a signal.
type Identity struct {
	kind identityKind
	raw  uint64
}

type identityKind uint8

const (
	// identityNone is the zero value: not read, or unreadable.
	identityNone identityKind = iota
	// identityKnown carries the creation stamp, in the unit of the OS.
	identityKnown
	// identityDeferred is Windows only: the listing stopped reading because its
	// budget ran out. raw is the listing instant (Unix ns); the stamp is read
	// when the confirmation opens (ConfirmIdentity).
	identityDeferred
)

// The Windows budget and slack (S-01b criterion 7, hypothesis H1).
const (
	// windowsIdentityBudget caps what reading identities adds to one refresh on
	// Windows. Past it the remaining PIDs are deferred. The starting value of the
	// story: adjust it from docs/measurements.
	windowsIdentityBudget = 100 * time.Millisecond
	// windowsBirthSlack is the granularity allowed between a creation time and the
	// listing instant before a process counts as born before the listing.
	windowsBirthSlack = 100 * time.Millisecond
)

// Verifiable reports whether a stop can still be attempted for the row: the
// identity is known, or deferred and read when the confirmation opens.
func (i Identity) Verifiable() bool { return i.kind != identityNone }

// Conflicts reports whether two identities say, with certainty, that they are
// two different processes: both known and different. An unknown or deferred one
// never conflicts.
func (i Identity) Conflicts(j Identity) bool {
	return i.kind == identityKnown && j.kind == identityKnown && i.raw != j.raw
}

// deferredAt is the identity of a PID not read at the listing taken at listedAt.
func deferredAt(listedAt time.Time) Identity {
	return Identity{kind: identityDeferred, raw: uint64(listedAt.UnixNano())} //nolint:gosec // listing instants are after 1970
}

// IdentityForTest builds a known identity for the fixtures of a test. It panics
// outside a test binary.
func IdentityForTest(raw uint64) Identity {
	mustBeUnderTest("IdentityForTest")
	return Identity{kind: identityKnown, raw: raw}
}

// DeferredIdentityForTest builds a deferred identity, as a Windows listing does
// for a PID it did not read in time. It panics outside a test binary.
func DeferredIdentityForTest(listedAt time.Time) Identity {
	mustBeUnderTest("DeferredIdentityForTest")
	return deferredAt(listedAt)
}

func mustBeUnderTest(name string) {
	if !testing.Testing() {
		panic("ports: " + name + " is reserved for tests (DEVDESK-709)")
	}
}

// UnverifiableError is the refusal when DevDesk cannot tell which process holds
// the PID. It is DevDesk's own decision, not the system's: it wraps no OS
// sentinel, so the interface cannot read it as "refused by the system".
type UnverifiableError struct {
	PID   int
	Cause error // for the log only; deliberately not returned by Unwrap
}

func (e *UnverifiableError) Error() string {
	return fmt.Sprintf("Cannot verify which process PID %d is — not stopped", e.PID)
}

// IdentityChangedError is the refusal when the PID is held by another process
// than the one that was listed.
type IdentityChangedError struct{ PID int }

func (e *IdentityChangedError) Error() string {
	return fmt.Sprintf("PID %d is no longer the process that was listed — not stopped", e.PID)
}

// parseStartTicks reads the starttime (field 22, ticks since boot) of a
// /proc/<pid>/stat line. The command name (field 2) sits between parentheses and
// may hold spaces and parentheses itself, so the fields are counted from the
// last ")".
func parseStartTicks(stat []byte) (uint64, error) {
	end := bytes.LastIndexByte(stat, ')')
	if end < 0 {
		return 0, errors.New("no closing parenthesis in the stat line")
	}
	// Fields 3 onward follow the name: field 22 is the 20th of them.
	const startIndex = 22 - 3
	fields := bytes.Fields(stat[end+1:])
	if len(fields) <= startIndex {
		return 0, fmt.Errorf("the stat line stops at field %d, before starttime (22)", len(fields)+2)
	}
	ticks, err := strconv.ParseUint(string(fields[startIndex]), 10, 64)
	if err != nil {
		return 0, fmt.Errorf("reading starttime from the stat line: %w", err)
	}
	return ticks, nil
}

// timevalStamp is a macOS process start (seconds and microseconds) as one value.
func timevalStamp(sec int64, usec int32) uint64 {
	return uint64(sec)*1_000_000 + uint64(usec) //nolint:gosec // a start time is positive
}

package ports

import (
	"os"
	"testing"
	"time"
)

// Helpers for the tests of this package that reach the process seams
// (DEVDESK-708, DEVDESK-709). The seams are package-level variables, so no test
// in this package may call t.Parallel: two tests swapping them would see each
// other.

// fakeEpoch is the instant a fakeOS clock starts at.
var fakeEpoch = time.Date(2026, time.November, 23, 12, 0, 0, 0, time.UTC)

// fakeOS is a substitute osProcs. It records every PID it was asked to kill and
// never signals anything.
type fakeOS struct {
	created   map[int]int64 // creation time per PID, in ms; opaque
	createErr map[int]error // a read error per PID

	ids     map[int]uint64 // raw identity per PID; a PID with no entry reads as gone
	idErr   map[int]error  // an identity read error per PID
	idCalls []int          // PIDs identity was called with, in order

	status     map[int]procStatus // what probe reads per PID; a PID with no entry reads as gone
	statusErr  map[int]error      // a probe read error per PID
	probeCalls []int              // PIDs probe was called with, in order

	killErr    error        // returned by every kill
	kills      []int        // PIDs kill was called with, in order
	killedWith []Identity   // the identity kill was called with, in order
	sigs       []stopSignal // the signal kill was asked to send, in order

	clock    time.Time     // what the `now` seam answers
	readStep time.Duration // how far every identity read moves the clock
}

func (f *fakeOS) createTime(pid int) (int64, error) {
	if err, ok := f.createErr[pid]; ok {
		return 0, err
	}
	return f.created[pid], nil
}

func (f *fakeOS) identity(pid int) (uint64, error) {
	f.idCalls = append(f.idCalls, pid)
	f.clock = f.clock.Add(f.readStep)
	if err, ok := f.idErr[pid]; ok {
		return 0, err
	}
	raw, ok := f.ids[pid]
	if !ok {
		return 0, os.ErrProcessDone
	}
	return raw, nil
}

// probe answers from status and statusErr and, like the real one, sends nothing.
func (f *fakeOS) probe(pid int) (procStatus, error) {
	f.probeCalls = append(f.probeCalls, pid)
	if err, ok := f.statusErr[pid]; ok {
		return procStatus{}, err
	}
	st, ok := f.status[pid]
	if !ok {
		return procStatus{}, os.ErrProcessDone
	}
	return st, nil
}

func (f *fakeOS) kill(pid int, want Identity, sig stopSignal) error {
	f.kills = append(f.kills, pid)
	f.killedWith = append(f.killedWith, want)
	f.sigs = append(f.sigs, sig)
	return f.killErr
}

// useFakeOS replaces the five seams (selfPID, parentPID, goos, now, procOS) and
// restores them when the test ends.
func useFakeOS(t *testing.T, self, parent int, goosName string) *fakeOS {
	t.Helper()
	oldSelf, oldParent, oldGOOS, oldNow, oldProc := selfPID, parentPID, goos, now, procOS
	t.Cleanup(func() {
		selfPID, parentPID, goos, now, procOS = oldSelf, oldParent, oldGOOS, oldNow, oldProc
	})

	fake := &fakeOS{
		created:   map[int]int64{},
		createErr: map[int]error{},
		ids:       map[int]uint64{},
		idErr:     map[int]error{},
		status:    map[int]procStatus{},
		statusErr: map[int]error{},
		clock:     fakeEpoch,
	}
	selfPID = func() int { return self }
	parentPID = func() int { return parent }
	goos = goosName
	now = func() time.Time { return fake.clock }
	procOS = fake
	return fake
}

// filetimeOf is the Windows FILETIME (100 ns ticks since 1601) of an instant.
func filetimeOf(t time.Time) uint64 {
	const unixEpochAsFiletime = 116444736000000000
	return uint64(t.UnixNano()/100) + unixEpochAsFiletime //nolint:gosec // test instants are after 1970
}

// allowRealSignals lets realOS.kill send a real signal for the rest of this
// test. Only a test that signals a child it started itself may call it; never
// one that aims at any other PID.
func allowRealSignals(t *testing.T) {
