// One read per probe, and nothing is ever sent: the probe is not a signal.
func TestProbeReadsOnceAndSendsNothing(t *testing.T) {
	fake := useFakeOS(t, 100, 99, "linux")
	fake.status[812] = procStatus{start: 7}

